/// The annotation and runtime for classes generated by `charcoal_builder`.
///
/// Annotate a class, add the generated mixin, and run `build_runner`:
///
/// ```dart
/// import 'package:charcoal/charcoal.dart';
///
/// part 'book.charcoal.g.dart';
///
/// @Charcoal()
/// final class const Book({
///   required this.title,
///   this.notes,
/// }) with BookCharcoal {
///   final String title;
///   final String? notes;
/// }
/// ```
///
/// It gains `toMap` and `toJsonString`, while `BookCharcoal` has the static
/// `fromMap`/`fromJsonString`.
library;

export 'package:meta/meta.dart' show immutable;

export 'src/adapters/adapters.dart';
export 'src/charcoal.dart';
export 'src/charcoal_adapter.dart';
export 'src/charcoal_exception.dart';
export 'src/charcoal_hash.dart';
export 'src/charcoal_json.dart';
export 'src/charcoal_json_reader.dart';
